let accessToken: string | null = null;

api.interceptors.response.use(undefined, async (error) => {
  if (error.response?.status !== 401) throw error;

  const res = await fetch('/auth/refresh', {
    method: 'POST',
    credentials: 'include'
  });
  if (!res.ok) throw error;

  const { access_token } = await res.json();
  accessToken = access_token;

  error.config.headers.Authorization = `Bearer ${accessToken}`;
  return api.request(error.config);
});

referenceAnswer:
There is no in-flight deduplication. Each 401 independently POSTs to /auth/refresh; with rotation the first call consumes the refresh token, and the two that were already in flight present the now-superseded one. A server implementing reuse detection (RFC 9700 s4.14) reads that as a replayed token and revokes the entire grant family, so the user is logged out by the app's own retry logic — and it only reproduces under concurrency, which is why it survives manual QA.

Share a single refresh promise between all waiters, and guard the retry so a permanently dead session cannot loop:

```ts
let refreshing: Promise<string> | null = null;

function refreshOnce(): Promise<string> {
  refreshing ??= fetch('/auth/refresh', { method: 'POST', credentials: 'include' })
    .then((r) => {
      if (!r.ok) throw new Error('refresh failed');
      return r.json();
    })
    .then((d) => d.access_token as string)
    .finally(() => {
      refreshing = null;
    });
  return refreshing;
}

api.interceptors.response.use(undefined, async (error) => {
  if (error.response?.status !== 401 || error.config._retried) throw error;
  error.config._retried = true;
  const token = await refreshOnce();
  error.config.headers.Authorization = `Bearer ${token}`;
  return api.request(error.config);
});
```

