// app/api/invoices/route.ts
export async function GET(req: Request) {
  const userId = req.headers.get('x-user-id');
  if (!userId) return new Response(null, { status: 401 });

  const invoices = await db.invoice.findMany({ where: { userId } });
  return Response.json(invoices);
}

referenceAnswer:
A request header is attacker-controlled input, not an authentication result. Two things go wrong at once: the matcher negative-lookahead excludes `api`, so the proxy never runs for this route handler and the header the app reads is whatever the client sent; and even on a covered route the proxy only sets `x-user-id` when a session exists — it never deletes an inbound one, so a forged value survives on any unauthenticated request. `curl -H 'x-user-id: <someone-else>' /api/invoices` reads another tenant's invoices with no session at all.

Fix: derive identity inside the route handler from the session itself, through the same Data Access Layer every other read uses:

```ts
export async function GET() {
  const { userId } = await verifySession(); // reads + verifies the cookie, redirects/401s on failure
  const invoices = await db.invoice.findMany({ where: { userId } });
  return Response.json(invoices);
}
```

If a forwarded header is genuinely wanted for tracing, strip it from the incoming request before setting it (`headers.delete('x-user-id')` first) and still never use it as an authorization input.

